begin;
select set_config('ex.a',gen_random_uuid()::text,true),set_config('ex.b',gen_random_uuid()::text,true),set_config('ex.c',gen_random_uuid()::text,true),set_config('ex.p',gen_random_uuid()::text,true),set_config('ex.s',gen_random_uuid()::text,true),set_config('ex.customer',gen_random_uuid()::text,true),set_config('ex.buy',gen_random_uuid()::text,true),set_config('ex.buy2',gen_random_uuid()::text,true),set_config('ex.sale1',gen_random_uuid()::text,true),set_config('ex.sale2',gen_random_uuid()::text,true);
insert into auth.users(id,email) values(current_setting('ex.a')::uuid,'export-a@example.invalid'),(current_setting('ex.b')::uuid,'export-b@example.invalid'),(current_setting('ex.c')::uuid,'export-c@example.invalid');
select set_config('request.jwt.claims',json_build_object('sub',current_setting('ex.a'),'role','authenticated')::text,true);
set local role authenticated;
insert into public.products(id,name,barcode,sale_price) values(current_setting('ex.p')::uuid,'Export product','001234',2000);
insert into public.suppliers(id,name) values(current_setting('ex.s')::uuid,'Export supplier');
insert into public.customers(id,name) values(current_setting('ex.customer')::uuid,'Export customer');
select public.post_cash_entry(gen_random_uuid(),'deposit',10000,'Float');
select public.post_supplier_purchase(current_setting('ex.buy')::uuid,jsonb_build_array(jsonb_build_object('product_id',current_setting('ex.p'),'quantity_units',10000,'unit_cost',1000)),current_setting('ex.s')::uuid,2000,'Export invoice','');
select public.post_supplier_purchase_payment(gen_random_uuid(),current_setting('ex.buy')::uuid,1000,'Invoice payment');
select public.post_purchase_return(gen_random_uuid(),current_setting('ex.buy')::uuid,'Partial supplier return',jsonb_build_array(jsonb_build_object('line_no',1,'quantity_units',500)));
select public.post_supplier_purchase(current_setting('ex.buy2')::uuid,jsonb_build_array(jsonb_build_object('product_id',current_setting('ex.p'),'quantity_units',1000,'unit_cost',1000)),current_setting('ex.s')::uuid,1000,'Return invoice','');
select public.post_purchase_reversal(gen_random_uuid(),current_setting('ex.buy2')::uuid,'Full supplier return');
select public.post_debt_entry(gen_random_uuid(),current_setting('ex.customer')::uuid,'charge',1000,'Old debt');
select public.post_debt_entry(gen_random_uuid(),current_setting('ex.customer')::uuid,'repayment',100,'Repayment');
select public.post_cash_sale(current_setting('ex.sale1')::uuid,jsonb_build_array(jsonb_build_object('product_id',current_setting('ex.p'),'quantity_units',1000,'expected_price',2000)),0,2000,'','');
select public.post_sale_reversal(gen_random_uuid(),current_setting('ex.sale1')::uuid,'Full return');
select public.post_cash_sale(current_setting('ex.sale2')::uuid,jsonb_build_array(jsonb_build_object('product_id',current_setting('ex.p'),'quantity_units',1000,'expected_price',2000)),0,2000,'','');
select public.post_sale_return(gen_random_uuid(),current_setting('ex.sale2')::uuid,'Partial return',jsonb_build_array(jsonb_build_object('line_no',1,'quantity_units',500)));
do $$declare p record;begin select * into p from public.stock_catalog where id=current_setting('ex.p')::uuid;perform public.post_stock_waste(gen_random_uuid(),p.id,p.quantity_units,p.stock_version::bigint,1,'Broken');end $$;
do $$declare p record;v jsonb;older jsonb;before_n bigint;i integer;begin
 select * into p from public.stock_catalog where id=current_setting('ex.p')::uuid;
 perform public.post_stock_adjustment(gen_random_uuid(),p.id,p.quantity_units,p.stock_version::bigint,p.quantity_units+10,'Profile count');
 select count(*) into before_n from public.stock_movements where product_id=p.id;
 v:=public.get_product_profile(p.id,0);
 if v#>>'{product,id}'<>p.id::text or v#>>'{product,name}'<>'Export product' or v#>>'{product,barcode}'<>'001234' or v->>'count'<>before_n::text or jsonb_array_length(v->'rows')<>before_n then raise exception 'profile snapshot wrong';end if;
 if jsonb_typeof(v#>'{product,sale_price}')<>'string' or jsonb_typeof(v#>'{product,quantity_units}')<>'string' or jsonb_typeof(v#>'{rows,0,movement_no}')<>'string' then raise exception 'exact number strings lost';end if;
 if v#>>'{product,stock_version}'<>v#>>'{rows,0,movement_no}' or v#>>'{product,quantity_units}'<>v#>>'{rows,0,balance_after}' then raise exception 'stock snapshot inconsistent';end if;
 if (select count(distinct r->>'source') from jsonb_array_elements(v->'rows') r)<>8 then raise exception 'movement source coverage incomplete';end if;
 for i in 1..53 loop perform public.post_purchase(gen_random_uuid(),jsonb_build_array(jsonb_build_object('product_id',p.id,'quantity_units',1,'unit_cost',1000)),'','Profile pagination','');end loop;
 select count(*) into before_n from public.stock_movements where product_id=p.id;
 v:=public.get_product_profile(p.id,0);older:=public.get_product_profile(p.id,1);
 if jsonb_array_length(v->'rows')<>50 or jsonb_array_length(older->'rows')<>before_n-50 or older->>'count'<>before_n::text then raise exception 'pagination count wrong';end if;
 if (v#>>'{rows,49,movement_no}')::bigint<=(older#>>'{rows,0,movement_no}')::bigint then raise exception 'pagination order wrong';end if;
 if (select count(*) from public.stock_movements where product_id=p.id)<>before_n then raise exception 'profile changed records';end if;
 begin perform public.get_product_profile(p.id,-1);raise exception 'bad page accepted';exception when raise_exception then if sqlerrm<>'product_profile_invalid_request' then raise;end if;end;
 begin perform public.get_product_profile(p.id,1000001);raise exception 'page cap accepted';exception when raise_exception then if sqlerrm<>'product_profile_invalid_request' then raise;end if;end;
end $$;
insert into public.products(name,sale_price) values('Empty profile',20);
do $$declare v jsonb;begin v:=public.get_product_profile((select id from public.products where name='Empty profile'));if v->>'count'<>'0' or v#>>'{product,quantity_units}'<>'0' or v#>>'{product,stock_version}'<>'0' or jsonb_array_length(v->'rows')<>0 then raise exception 'empty profile wrong';end if;end $$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',current_setting('ex.b'),'role','authenticated')::text,true);set local role authenticated;
do $$begin begin perform public.get_product_profile(current_setting('ex.p')::uuid);raise exception 'other owner profile exposed';exception when raise_exception then if sqlerrm<>'product_profile_unavailable' then raise;end if;end;end $$;
reset role;select set_config('request.jwt.claims','{}',true);set local role authenticated;
do $$begin begin perform public.get_product_profile(current_setting('ex.p')::uuid);raise exception 'no UID profile exposed';exception when raise_exception then if sqlerrm<>'product_profile_auth_required' then raise;end if;end;end $$;
reset role;set local role anon;
do $$begin begin perform public.get_product_profile(current_setting('ex.p')::uuid);raise exception 'anon profile exposed';exception when insufficient_privilege then null;end;end $$;
reset role;
